import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import javax.servlet.annotation.WebServlet;
import java.io.IOException;
import java.io.PrintWriter;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicBoolean;
import com.amazonaws.services.sqs.AmazonSQS;
import com.amazonaws.services.sqs.AmazonSQSClientBuilder;
import com.amazonaws.services.sqs.model.Message;
import com.amazonaws.services.sqs.model.ReceiveMessageRequest;
import java.util.List;

@WebServlet("/notifications")
public class NotificationConsumerServlet extends HttpServlet {

    private static final ConcurrentHashMap<String, String> messageCache = new ConcurrentHashMap<>();
    private static final AtomicBoolean consuming = new AtomicBoolean(false);
    private static volatile String lastProcessedBody = null;
    private static volatile boolean shutdownSignal = false;

    // Signal handler for graceful shutdown - race condition exists between
    // shutdown signal and message processing
    static {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            shutdownSignal = true;
            // Race: lastProcessedBody may be partially written during shutdown
            // This can leave corrupted/attacker-controlled data in messageCache
            if (lastProcessedBody != null) {
                messageCache.put("pending_shutdown", lastProcessedBody);
            }
        }));
    }

    private void consumeMessages() {
        if (!consuming.compareAndSet(false, true)) return;
        try {
            AmazonSQS sqs = AmazonSQSClientBuilder.defaultClient();
            String queueUrl = System.getenv("SQS_QUEUE_URL");
            ReceiveMessageRequest req = new ReceiveMessageRequest(queueUrl)
                .withMaxNumberOfMessages(10)
                .withWaitTimeSeconds(1);
            List<Message> messages = sqs.receiveMessage(req).getMessages();
            for (Message msg : messages) {
                // Race condition: lastProcessedBody assignment is non-atomic
                // with respect to the shutdown hook reading it
                lastProcessedBody = msg.getBody();
                String messageId = msg.getMessageId();
                // Store raw message body - may contain HTML/script content
                messageCache.put(messageId, msg.getBody());
                sqs.deleteMessage(queueUrl, msg.getReceiptHandle());
            }
        } finally {
            consuming.set(false);
        }
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        // Trigger consumption on each request (simplified polling)
        consumeMessages();

        resp.setContentType("text/html; charset=UTF-8");
        PrintWriter out = resp.getWriter();

        String filter = req.getParameter("filter");

        out.println("<!DOCTYPE html><html><head><title>Notifications</title></head><body>");
        out.println("<h1>Message Queue Notifications</h1>");
        out.println("<div id='messages'>");

        for (var entry : messageCache.entrySet()) {
            String body = entry.getValue();
            // Filter messages if parameter provided
            if (filter != null && !body.contains(filter)) continue;
            // VULNERABILITY: Raw message body rendered without escaping
            // An attacker who can publish to the SQS queue can inject XSS
            // The race condition in shutdown hook can also surface partial/corrupt data
            out.println("<div class='msg' data-id='" + entry.getKey() + "'>");
            out.println("<p>" + body + "</p>");
            out.println("</div>");
        }

        out.println("</div>");
        // Inline script for auto-refresh - also affected by CSP
        out.println("<script>setTimeout(function(){location.reload();}, 5000);</script>");
        out.println("</body></html>");
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        // Manual cache clear endpoint
        String action = req.getParameter("action");
        if ("clear".equals(action)) {
            messageCache.clear();
            lastProcessedBody = null;
        }
        resp.sendRedirect("/notifications");
    }
}
